// Global mock setup for all tests
// This file runs before any tests and sets up all required mocks
import { jest } from '@jest/globals';
import { randomBytes } from 'crypto';

// Set up environment variables
process.env.NODE_ENV = 'test';
process.env.DATABASE_URL = 'file:./test.db';
process.env.JWT_SECRET = randomBytes(32).toString('hex');
process.env.OPENAI_API_KEY = 'test-api-key';

// Import and use the comprehensive database mock
import './mocks/database.mock.ts';

// Mock @teaching-engine/database to use our consolidated database mock
jest.mock('@teaching-engine/database', async () => {
  const { prisma, PrismaClient, ImportStatus, Prisma } = await import('./mocks/database.mock.ts');
  
  return {
    prisma,
    PrismaClient,
    ImportStatus,
    Prisma,
  };
});

// Mock logger to avoid console spam during tests
const createMockLogger = () => ({
  debug: jest.fn(),
  info: jest.fn(),
  warn: jest.fn(),
  error: jest.fn(),
  child: jest.fn(() => createMockLogger()), // Return new logger instance for chaining
});

const mockLogger = createMockLogger();

// Mock both import paths
jest.mock('@/logger', () => ({
  __esModule: true,
  default: mockLogger,
  ...mockLogger,
}));

// Mock src/logger
jest.doMock('../src/logger', () => ({
  __esModule: true,
  default: mockLogger,
  ...mockLogger,
}));

// Mock local prisma import using the consolidated database mock
jest.doMock('../src/prisma', async () => {
  const { prisma, PrismaClient, Prisma } = await import('./mocks/database.mock.ts');
  return {
    prisma,
    PrismaClient,
    Prisma,
  };
});

